//! Fee-on-transfer fungible token analogue for the Vegeta S3 fee-token family.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{pub admin:String,pub fee_collector:String,pub fee_bps:u16,#[serde(default)]pub initial_balances:Vec<InitialBalance>}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InitialBalance{pub address:String,pub amount:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{Transfer{recipient:String,amount:Uint128},TransferFrom{owner:String,recipient:String,amount:Uint128},Approve{spender:String,amount:Uint128},SetPolicy{fee_bps:u16,fee_collector:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{Balance{address:String},Allowance{owner:String,spender:String},TotalSupply{},Policy{}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Config{pub admin:Addr,pub fee_collector:Addr,pub fee_bps:u16}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct AmountResponse{pub amount:Uint128}
const CONFIG:Item<Config>=Item::new("config");const TOTAL_SUPPLY:Item<Uint128>=Item::new("total_supply");const BALANCES:Map<&str,Uint128>=Map::new("balances");const ALLOWANCES:Map<(&str,&str),Uint128>=Map::new("allowances");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("unauthorized")]Unauthorized,#[error("invalid fee")]InvalidFee,#[error("insufficient funds")]InsufficientFunds,#[error("insufficient allowance")]InsufficientAllowance}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{if msg.fee_bps>10_000{return Err(ContractError::InvalidFee)};CONFIG.save(deps.storage,&Config{admin:deps.api.addr_validate(&msg.admin)?,fee_collector:deps.api.addr_validate(&msg.fee_collector)?,fee_bps:msg.fee_bps})?;let mut total=Uint128::zero();for b in msg.initial_balances{let a=deps.api.addr_validate(&b.address)?;BALANCES.save(deps.storage,a.as_str(),&b.amount)?;total=total.checked_add(b.amount).map_err(StdError::overflow)?;}TOTAL_SUPPLY.save(deps.storage,&total)?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Transfer{recipient,amount}=>move_tokens(deps,info.sender.as_str(),&recipient,amount),ExecuteMsg::TransferFrom{owner,recipient,amount}=>{let o=deps.api.addr_validate(&owner)?;let a=ALLOWANCES.may_load(deps.storage,(o.as_str(),info.sender.as_str()))?.unwrap_or_default();if a<amount{return Err(ContractError::InsufficientAllowance)};ALLOWANCES.save(deps.storage,(o.as_str(),info.sender.as_str()),&a.checked_sub(amount).map_err(StdError::overflow)?)?;move_tokens(deps,o.as_str(),&recipient,amount)},ExecuteMsg::Approve{spender,amount}=>{let s=deps.api.addr_validate(&spender)?;ALLOWANCES.save(deps.storage,(info.sender.as_str(),s.as_str()),&amount)?;Ok(Response::new())},ExecuteMsg::SetPolicy{fee_bps,fee_collector}=>{let mut c=CONFIG.load(deps.storage)?;if c.admin!=info.sender{return Err(ContractError::Unauthorized)};if fee_bps>10_000{return Err(ContractError::InvalidFee)};c.fee_bps=fee_bps;c.fee_collector=deps.api.addr_validate(&fee_collector)?;CONFIG.save(deps.storage,&c)?;Ok(Response::new())}}}
fn move_tokens(deps:DepsMut,from:&str,to:&str,amount:Uint128)->Result<Response,ContractError>{let to=deps.api.addr_validate(to)?;let c=CONFIG.load(deps.storage)?;let x=BALANCES.may_load(deps.storage,from)?.unwrap_or_default();if x<amount{return Err(ContractError::InsufficientFunds)};let fee=amount.multiply_ratio(c.fee_bps as u128,10_000u128);let net=amount.checked_sub(fee).map_err(StdError::overflow)?;BALANCES.save(deps.storage,from,&x.checked_sub(amount).map_err(StdError::overflow)?)?;credit(deps.storage,to.as_str(),net)?;credit(deps.storage,c.fee_collector.as_str(),fee)?;Ok(Response::new())}
fn credit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->StdResult<()>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();BALANCES.save(s,a,&x.checked_add(n).map_err(StdError::overflow)?) }
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::Balance{address}=>to_json_binary(&AmountResponse{amount:BALANCES.may_load(deps.storage,&address)?.unwrap_or_default()}),QueryMsg::Allowance{owner,spender}=>to_json_binary(&AmountResponse{amount:ALLOWANCES.may_load(deps.storage,(owner.as_str(),spender.as_str()))?.unwrap_or_default()}),QueryMsg::TotalSupply{}=>to_json_binary(&AmountResponse{amount:TOTAL_SUPPLY.load(deps.storage)?}),QueryMsg::Policy{}=>to_json_binary(&CONFIG.load(deps.storage)?)}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::from_json;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn transfer_splits_fee(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{admin:"admin".into(),fee_collector:"fees".into(),fee_bps:100,initial_balances:vec![InitialBalance{address:"alice".into(),amount:Uint128::new(1000)}]}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::Transfer{recipient:"bob".into(),amount:Uint128::new(100)}).unwrap();assert_eq!(BALANCES.load(d.as_ref().storage,"bob").unwrap(),Uint128::new(99));assert_eq!(BALANCES.load(d.as_ref().storage,"fees").unwrap(),Uint128::new(1));let raw=query(d.as_ref(),mock_env(),QueryMsg::TotalSupply{}).unwrap();let r:AmountResponse=from_json(raw).unwrap();assert_eq!(r.amount,Uint128::new(1000));}}
